import{_ as a,o as e,c as n,a2 as r}from"./chunks/framework.XXezeKOl.js";const u=JSON.parse('{"title":"框架全景与选型","description":"先回答\\"要不要用框架\\"，再按语言、场景和团队情况在 LangGraph、Agents SDK、LlamaIndex、CrewAI、Eino、Spring AI 等之间做选择。","frontmatter":{"title":"框架全景与选型","description":"先回答\\"要不要用框架\\"，再按语言、场景和团队情况在 LangGraph、Agents SDK、LlamaIndex、CrewAI、Eino、Spring AI 等之间做选择。"},"headers":[],"relativePath":"guide/11-frameworks/overview.md","filePath":"guide/11-frameworks/overview.md","lastUpdated":null}'),d={name:"guide/11-frameworks/overview.md"};function i(o,t,s,l,h,g){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="框架全景与选型" tabindex="-1">框架全景与选型 <a class="header-anchor" href="#框架全景与选型" aria-label="Permalink to &quot;框架全景与选型&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>理解 Agent 框架到底帮你做了什么，以及什么时候不需要框架</li><li>认识 Python、Go、Java 三个生态中主流框架的定位</li><li>掌握一套可落地的选型方法，而不是跟风选&quot;最火&quot;的那个</li><li>了解使用框架时如何控制锁定风险</li></ul></div><h2 id="先问-需要框架吗" tabindex="-1">先问：需要框架吗 <a class="header-anchor" href="#先问-需要框架吗" aria-label="Permalink to &quot;先问：需要框架吗&quot;">​</a></h2><p>如果你跟着本站做过 <a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a>，会发现一个能用的 Agent 核心只有几十行：调模型、解析工具调用、执行工具、追加消息、循环。那框架的价值在哪？</p><p>框架真正帮你省事的，是这些&quot;手写也能做，但做好很费劲&quot;的部分：</p><table tabindex="0"><thead><tr><th>能力</th><th>手写难度</th><th>框架通常提供</th></tr></thead><tbody><tr><td>多模型适配</td><td>低（OpenAI 兼容接口已覆盖大部分）</td><td>统一的模型抽象，切换厂商改一行</td></tr><tr><td>工具定义</td><td>中（手写 JSON Schema 容易出错）</td><td>从函数签名、注解自动生成 Schema</td></tr><tr><td>状态持久化与恢复</td><td>高</td><td>Checkpoint，任务中断后从断点继续</td></tr><tr><td>人在环路</td><td>高</td><td>在指定步骤暂停，等待人工审批后恢复</td></tr><tr><td>复杂流程编排</td><td>高</td><td>图、分支、并行、子流程</td></tr><tr><td>可观测性</td><td>中</td><td>内置 Trace，对接 LangSmith、Langfuse 等</td></tr><tr><td>RAG 管道</td><td>中</td><td>文档加载、切分、索引、检索的现成组件</td></tr></tbody></table><p>所以判断标准很简单：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的需求只是&quot;模型 + 几个工具 + 循环&quot;？</span></span>
<span class="line"><span>   ├─ 是 ──▶ 手写或用轻量 SDK（OpenAI Agents SDK 等）就够了</span></span>
<span class="line"><span>   └─ 否，需要以下任一项：</span></span>
<span class="line"><span>        · 长流程且要能中断恢复</span></span>
<span class="line"><span>        · 人工审批节点</span></span>
<span class="line"><span>        · 多 Agent 协作、复杂分支</span></span>
<span class="line"><span>        · 大量文档的 RAG</span></span>
<span class="line"><span>      ──▶ 选一个擅长该领域的框架</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>一个务实的建议：<strong>先手写一遍，理解原理后再上框架</strong>。这样框架出问题时，你知道它底层在干什么，也能判断某个抽象是在帮你还是在碍事。</p><h2 id="三个生态的主流框架" tabindex="-1">三个生态的主流框架 <a class="header-anchor" href="#三个生态的主流框架" aria-label="Permalink to &quot;三个生态的主流框架&quot;">​</a></h2><h3 id="python-选择最多" tabindex="-1">Python：选择最多 <a class="header-anchor" href="#python-选择最多" aria-label="Permalink to &quot;Python：选择最多&quot;">​</a></h3><p>Python 是 Agent 生态的主战场，几乎所有新框架都先出 Python 版。</p><table tabindex="0"><thead><tr><th>框架</th><th>定位</th><th>适合</th></tr></thead><tbody><tr><td><a href="/guide/11-frameworks/langgraph">LangGraph</a></td><td>以&quot;状态图&quot;建模 Agent，强调可控性、持久化、人在环路</td><td>复杂、长流程、需要精确控制的生产级 Agent</td></tr><tr><td>LangChain</td><td>模型、工具、检索等组件的集成库，v1 起以 <code>create_agent</code> 为主入口，底层基于 LangGraph</td><td>快速搭建、需要丰富集成</td></tr><tr><td><a href="/guide/11-frameworks/agent-sdks">OpenAI Agents SDK</a></td><td>轻量：Agent、工具、交接（handoff）、护栏</td><td>快速搭建多 Agent 原型，概念少</td></tr><tr><td><a href="/guide/11-frameworks/agent-sdks">Claude Agent SDK</a></td><td>把 Claude Code 的 Agent 运行时作为库提供，自带文件、命令等工具</td><td>编码、运维、文件处理类 Agent</td></tr><tr><td><a href="/guide/11-frameworks/llamaindex-crewai">LlamaIndex</a></td><td>以数据和检索为中心</td><td>RAG、文档问答、知识库</td></tr><tr><td><a href="/guide/11-frameworks/llamaindex-crewai">CrewAI</a></td><td>角色扮演式多 Agent 团队</td><td>内容生产、调研等流程清晰的多角色协作</td></tr><tr><td><a href="/guide/11-frameworks/llamaindex-crewai">AutoGen</a></td><td>微软出品的多 Agent 对话框架</td><td>研究和实验多 Agent 对话模式</td></tr></tbody></table><h3 id="go-云原生与高并发" tabindex="-1">Go：云原生与高并发 <a class="header-anchor" href="#go-云原生与高并发" aria-label="Permalink to &quot;Go：云原生与高并发&quot;">​</a></h3><p>Go 生态更注重性能、类型安全和工程化，框架数量少但质量不错。</p><table tabindex="0"><thead><tr><th>框架</th><th>定位</th><th>适合</th></tr></thead><tbody><tr><td><a href="/guide/11-frameworks/go-eino">Eino</a></td><td>字节跳动 CloudWeGo 开源，组件 + 编排（Chain / Graph），强类型</td><td>国内大厂风格的生产级 Go 服务</td></tr><tr><td><a href="/guide/11-frameworks/go-eino">langchaingo</a></td><td>社区维护的 LangChain Go 移植</td><td>熟悉 LangChain 概念、需要较多集成</td></tr><tr><td>官方 SDK + 手写</td><td>openai-go 等官方 SDK 或直接 HTTP</td><td>需求简单、追求可控和零依赖</td></tr></tbody></table><h3 id="java-企业级集成" tabindex="-1">Java：企业级集成 <a class="header-anchor" href="#java-企业级集成" aria-label="Permalink to &quot;Java：企业级集成&quot;">​</a></h3><p>Java 生态的优势在于和现有企业系统（Spring、数据库、消息队列、权限体系）的无缝集成。</p><table tabindex="0"><thead><tr><th>框架</th><th>定位</th><th>适合</th></tr></thead><tbody><tr><td><a href="/guide/11-frameworks/java-spring-ai">Spring AI</a></td><td>Spring 官方项目，<code>ChatClient</code> 流式 API、自动配置、Advisor 机制</td><td>已经是 Spring Boot 技术栈的团队</td></tr><tr><td><a href="/guide/11-frameworks/java-spring-ai">LangChain4j</a></td><td>独立于 Spring，<code>AiServices</code> 声明式接口</td><td>非 Spring 项目，或偏好声明式写法</td></tr><tr><td>Spring AI Alibaba</td><td>基于 Spring AI，加强了阿里云生态和多 Agent 编排</td><td>使用通义千问、阿里云的团队</td></tr></tbody></table><h3 id="无代码与低代码" tabindex="-1">无代码与低代码 <a class="header-anchor" href="#无代码与低代码" aria-label="Permalink to &quot;无代码与低代码&quot;">​</a></h3><p><a href="/guide/11-frameworks/low-code">Dify、Coze</a> 等平台用可视化方式搭建 Agent 和工作流，适合业务人员快速验证想法，也能通过 API 嵌入到业务系统中。</p><h2 id="跨语言选型总表" tabindex="-1">跨语言选型总表 <a class="header-anchor" href="#跨语言选型总表" aria-label="Permalink to &quot;跨语言选型总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>Python</th><th>Go</th><th>Java</th></tr></thead><tbody><tr><td>入门学习、理解原理</td><td>手写 + openai SDK</td><td>手写 + net/http</td><td>手写 + HttpClient</td></tr><tr><td>简单工具 Agent</td><td>OpenAI Agents SDK</td><td>Eino ReAct Agent</td><td>Spring AI ChatClient + @Tool</td></tr><tr><td>复杂流程、可中断恢复</td><td>LangGraph</td><td>Eino Graph</td><td>Spring AI Alibaba Graph / 自研状态机</td></tr><tr><td>RAG 知识库</td><td>LlamaIndex</td><td>Eino / langchaingo 检索组件</td><td>Spring AI / LangChain4j RAG</td></tr><tr><td>多 Agent 协作</td><td>LangGraph、CrewAI、OpenAI Agents SDK</td><td>Eino 多 Agent 组件</td><td>Spring AI Alibaba、LangChain4j</td></tr><tr><td>编码 / 文件操作 Agent</td><td>Claude Agent SDK</td><td>调用 Claude Code CLI 或手写</td><td>手写</td></tr><tr><td>已有大量存量服务</td><td>看团队主语言</td><td>和现有 Go 微服务放一起</td><td>和现有 Spring 服务放一起</td></tr></tbody></table><p>最后一行往往是决定性的：<strong>团队主力语言和现有基础设施，比框架本身的功能差异更重要</strong>。一个 Java 团队为了用 LangGraph 引入 Python 服务，换来的是两套部署、两套监控和跨语言调用的复杂度。反过来，如果 Agent 是一个独立的新服务、团队也有 Python 能力，Python 生态的丰富度就是实实在在的优势。</p><h2 id="选型的五个问题" tabindex="-1">选型的五个问题 <a class="header-anchor" href="#选型的五个问题" aria-label="Permalink to &quot;选型的五个问题&quot;">​</a></h2><ol><li><strong>语言与基础设施</strong>：团队用什么语言？Agent 要和哪些现有系统打交道？</li><li><strong>控制力需求</strong>：你需要精确控制每一步（选图编排类），还是让模型自己决定流程（选轻量 Agent 类）？</li><li><strong>持久化与人在环路</strong>：任务会跑多久？要不要中途审批？这是手写最难做好的部分。</li><li><strong>模型绑定</strong>：框架是否支持你要用的模型厂商（尤其是国内模型）？OpenAI 兼容接口通常是最大公约数。</li><li><strong>成熟度与活跃度</strong>：版本是否稳定、文档是否跟得上、社区是否活跃、最近半年是否有破坏性变更。</li></ol><h2 id="控制锁定风险" tabindex="-1">控制锁定风险 <a class="header-anchor" href="#控制锁定风险" aria-label="Permalink to &quot;控制锁定风险&quot;">​</a></h2><p>Agent 框架普遍迭代很快，一年内出现大版本的破坏性变更是常态。几个降低风险的做法：</p><ul><li><strong>业务逻辑与框架解耦</strong>：工具函数写成普通函数，提示词放在独立文件，框架只负责&quot;粘合&quot;。换框架时这些都能复用。</li><li><strong>工具用 MCP 暴露</strong>：把工具做成 <a href="/guide/10-mcp/mcp-server">MCP Server</a>，任何框架都能接入。</li><li><strong>锁定版本</strong>：依赖写精确版本，升级前跑一遍 <a href="/guide/14-evaluation/regression">回归测试</a>。</li><li><strong>评估先行</strong>：有了 <a href="/guide/14-evaluation/eval-design">评估集</a>，换框架、换模型时才知道效果有没有退化。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>为了用框架而用框架</strong>：三个工具的简单 Agent 引入一个重型框架，调试时要穿过好几层抽象才能看到真实的 prompt。</li><li><strong>看过时教程</strong>：框架 API 变化快，搜到的博客可能是一年前的写法。以官方文档和你锁定的版本为准。</li><li><strong>混用多个框架</strong>：一个项目里同时用 LangChain、LlamaIndex 和 CrewAI，各自有一套消息格式和工具抽象，组合起来很难维护。</li><li><strong>忽略框架发出的真实请求</strong>：框架会在背后拼接系统提示词、改写工具描述。开启 Trace 看清实际发给模型的内容，参考 <a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a>。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><ol><li>一个 Agent 只需要调用 3 个内部 API 回答员工问题，团队用 Go，你会怎么选？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>优先考虑手写或用轻量方案：Go 标准库调用 OpenAI 兼容接口加一个简单循环即可；如果希望少写样板代码，可以用 Eino 的 ReAct Agent。不需要引入复杂的图编排。</p></details><ol start="2"><li>什么样的需求最能体现 LangGraph 这类图编排框架相对手写的价值？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>长时间运行、需要中断后恢复（Checkpoint）、需要在特定步骤等待人工审批、流程有复杂分支或循环的场景。这些手写需要自己实现状态持久化和恢复逻辑，成本高且容易出错。</p></details><ol start="3"><li>列举两种降低框架锁定风险的做法。</li></ol><details class="details custom-block"><summary>查看答案</summary><p>例如：工具和业务逻辑写成与框架无关的普通函数或 MCP Server；提示词独立管理；锁定依赖版本；建立评估集，升级或迁移框架时用回归测试验证效果。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>本模块各框架详解：<a href="/guide/11-frameworks/langgraph">LangGraph</a>、<a href="/guide/11-frameworks/agent-sdks">Claude Agent SDK 与 OpenAI Agents SDK</a>、<a href="/guide/11-frameworks/llamaindex-crewai">LlamaIndex、CrewAI 与 AutoGen</a>、<a href="/guide/11-frameworks/go-eino">Go：Eino 与 langchaingo</a>、<a href="/guide/11-frameworks/java-spring-ai">Java：Spring AI 与 LangChain4j</a>、<a href="/guide/11-frameworks/low-code">低代码平台：Dify 与 Coze</a></li><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Building effective agents（Anthropic 工程博客）</a></li><li>学习路径参考：<a href="/roadmap/engineer">工程师路径</a></li></ul>`,40)])])}const c=a(d,[["render",i]]);export{u as __pageData,c as default};
